def f(n):
    """Returns the largest odd divisor of n."""
    if n <= 0:
        raise ValueError("Input must be a positive integer.")
    while n % 2 == 0:
        n //= 2
    return n

def check_condition(u, v):
    """Checks if f(u+k+v) - f(u+k) is a multiple of 4 for k=0 to v-1."""
    for k in range(v):
        diff = f(u + k + v) - f(u + k)
        if diff % 4 != 0:
            # print(f"Failed at k={k}: f({u+k+v}) - f({u+k}) = {diff}. {diff} % 4 = {diff % 4}")
            return False
    return True

# Search for the smallest u when v=12
v_target = 12
search_limit = 5000 # Increased search limit for thoroughness

smallest_u = None
for u_candidate in range(1, search_limit + 1):
    if check_condition(u_candidate, v_target):
        smallest_u = u_candidate
        break

print(f"Smallest u found for v={v_target} up to search limit {search_limit}: {smallest_u}")
